#!/usr/bin/env bash
# ╔══════════════════════════════════════════════════════════════════════╗
#   arreglar-zero-rice.sh — script maestro de la versión 0.3.0
#
#   1. Respalda tu repo (rama de respaldo + stash si tienes cambios sin guardar)
#   2. Pone los archivos corregidos y la captura del escritorio en el repo
#   3. Revisa que todo esté bien (sintaxis, shellcheck, Lua)
#   4. Hace el commit
#   5. Instala lo corregido en tu ~/.config y arregla el bloqueo en vivo
#   6. Sube todo a GitHub (y si quieres, lo pasa a main para que se vea en la página)
#
#   bash arreglar-zero-rice.sh                 pregunta antes de cada paso
#   bash arreglar-zero-rice.sh --si            dice que sí a todo
#   bash arreglar-zero-rice.sh --repo ~/ruta   si tu repo no está en ~/zero-rice
#   bash arreglar-zero-rice.sh --sin-subir     todo menos el git push
#   bash arreglar-zero-rice.sh --sin-instalar  solo el repo, sin tocar ~/.config
# ╚══════════════════════════════════════════════════════════════════════╝
set -uo pipefail

VERSION_NUEVA="0.3.0"
REMOTO_ESPERADO="Zer0-HMA/zero-rice"
SI=0; SUBIR=1; INSTALAR=1; REPO=""
while (($#)); do
  case "$1" in
    --si|-y)        SI=1 ;;
    --sin-subir)    SUBIR=0 ;;
    --sin-instalar) INSTALAR=0 ;;
    --repo)         shift; REPO="${1:-}" ;;
    --repo=*)       REPO="${1#--repo=}" ;;
    -h|--help)      sed -n '2,18p' "${BASH_SOURCE[0]}"; exit 0 ;;
    *) echo "Opción desconocida: $1 (usa --help)"; exit 1 ;;
  esac
  shift
done

titulo() { printf '\n\e[1;35m━━━ %s ━━━\e[0m\n' "$*"; }
ok()     { printf '\e[1;32m[✓]\e[0m %s\n' "$*"; }
info()   { printf '\e[1;36m[i]\e[0m %s\n' "$*"; }
warn()   { printf '\e[1;33m[!]\e[0m %s\n' "$*"; }
error()  { printf '\e[1;31m[✗]\e[0m %s\n' "$*"; }
morir()  { error "$*"; exit 1; }
preguntar() {   # pregunta "texto" [s|n]  (por defecto sí)
  ((SI)) && return 0
  local r def=${2:-s}
  if [[ $def == s ]]; then read -rp "$(printf '\e[1;36m[?]\e[0m') $1 [S/n] " r || r=n; [[ ! $r =~ ^[nN] ]]
  else read -rp "$(printf '\e[1;36m[?]\e[0m') $1 [s/N] " r || r=n; [[ $r =~ ^[sSyY] ]]; fi
}

SELF=$(readlink -f "$0")
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
FECHA=$(date +%Y%m%d-%H%M%S)

cat <<'BANNER'

   ███████╗███████╗██████╗  ██████╗
   ╚══███╔╝██╔════╝██╔══██╗██╔═══██╗     script maestro · 0.3.0
     ███╔╝ █████╗  ██████╔╝██║   ██║     arregla el bloqueo, recupera la 0.2.0
    ███╔╝  ██╔══╝  ██████╔╝██║   ██║     y sube la captura al repo
   ███████╗███████╗██║  ██║╚██████╔╝
   ╚══════╝╚══════╝╚═╝  ╚═╝ ╚═════╝
BANNER

[[ $EUID -eq 0 ]] && morir "No lo corras como root ni con sudo; usa tu usuario (pedirá sudo solo si hace falta)."
for c in git tar base64 gzip; do command -v "$c" >/dev/null 2>&1 || morir "Falta '$c' (sudo pacman -S $c)"; done

# los archivos corregidos viajan dentro de este mismo script: se desempacan antes de tocar nada
LINEA=$(awk '/^__PAYLOAD_ABAJO__$/ { print NR + 1; exit }' "$SELF")
[[ -n $LINEA ]] || morir "El script está incompleto (no trae los archivos). Descárgalo otra vez."
tail -n +"$LINEA" "$SELF" | base64 -d | tar -xz -C "$TMP" || morir "No pude desempacar los archivos (¿el script se descargó completo?)"
mapfile -t ARCHIVOS < <(cd "$TMP" && find . -type f | sed 's|^\./||' | sort)
((${#ARCHIVOS[@]} > 10)) || morir "El paquete de archivos está incompleto. Descarga el script otra vez."

# ═════════════════════ 1. Encontrar el repo ═════════════════════
titulo "1. Buscando tu repo de zero-rice"
es_repo() { [[ -d "$1/.git" && -f "$1/install.sh" && -d "$1/config/hypr" ]]; }
if [[ -z $REPO ]]; then
  for d in "$PWD" "$HOME/zero-rice" "$HOME/Documentos/zero-rice" "$HOME/Documents/zero-rice" "$HOME/git/zero-rice" "$HOME/proyectos/zero-rice"; do
    es_repo "$d" && { REPO=$d; break; }
  done
fi
if [[ -z $REPO ]]; then
  REPO=$(find "$HOME" -maxdepth 4 -type d -name .git -path '*zero-rice*' 2>/dev/null | head -1); REPO=${REPO%/.git}
fi
if [[ -z $REPO ]] || ! es_repo "$REPO"; then
  warn "No encontré tu repo de zero-rice."
  preguntar "¿Lo clono en ~/zero-rice?" || morir "Dime dónde está con:  bash $SELF --repo ~/ruta/zero-rice"
  git clone "https://github.com/$REMOTO_ESPERADO.git" "$HOME/zero-rice" || morir "No se pudo clonar"
  REPO="$HOME/zero-rice"
fi
REPO=$(cd "$REPO" && pwd)
cd "$REPO" || morir "No puedo entrar a $REPO"
URL=$(git remote get-url origin 2>/dev/null || true)
ok "Repo: $REPO"
info "Remoto: ${URL:-(sin remoto)}"
[[ $URL == *"$REMOTO_ESPERADO"* ]] || warn "El remoto no es $REMOTO_ESPERADO; sigo, pero revisa antes de subir."

if [[ -d .git/rebase-merge || -d .git/rebase-apply || -f .git/MERGE_HEAD ]]; then
  morir "Tienes un merge o rebase a medias. Termínalo o cancélalo (git merge --abort / git rebase --abort) y vuelve a correr esto."
fi
RAMA=$(git symbolic-ref --short HEAD 2>/dev/null) || morir "Estás en un HEAD separado; cámbiate a una rama (git switch feat/zero-lock) y vuelve a correrlo."
ok "Rama actual: $RAMA"
if [[ $(cat VERSION 2>/dev/null) == "$VERSION_NUEVA" ]] && grep -q 'VERSION="1.2.0"' config/hypr/scripts/zero-lock.sh 2>/dev/null; then
  info "Este repo ya tiene la $VERSION_NUEVA; solo se volverán a escribir los archivos (si algo cambió)."
fi

# ═════════════════════ 2. Respaldo ═════════════════════
titulo "2. Respaldo (nada se pierde)"
RESPALDO="respaldo/antes-de-$VERSION_NUEVA-$FECHA"
git branch "$RESPALDO" HEAD || morir "No pude crear la rama de respaldo"
ok "Rama de respaldo: $RESPALDO  (para volver atrás: git reset --hard $RESPALDO)"
STASH=0
if [[ -n $(git status --porcelain) ]]; then
  git stash push -u -m "zero-rice: cambios sin guardar antes de $VERSION_NUEVA ($FECHA)" >/dev/null || morir "No pude guardar tus cambios sin commit"
  STASH=1
  ok "Tenías cambios sin commit: quedaron guardados en  git stash list  (recupéralos con: git stash pop)"
fi

# ═════════════════════ 3. Archivos corregidos ═════════════════════
titulo "3. Poniendo los archivos corregidos"

# ¿tu commit sin subir tocó alguno de estos archivos?
if git rev-parse --verify -q "@{upstream}" >/dev/null; then
  mapfile -t TUYOS < <(git diff --name-only "@{upstream}" HEAD 2>/dev/null)
  if ((${#TUYOS[@]})); then
    CHOQUES=()
    for a in "${TUYOS[@]}"; do for b in "${ARCHIVOS[@]}"; do [[ $a == "$b" ]] && CHOQUES+=("$a"); done; done
    if ((${#CHOQUES[@]})); then
      warn "Tus commits sin subir también cambiaron: ${CHOQUES[*]}"
      warn "Se reemplazan por la versión corregida; tu versión queda en la rama $RESPALDO"
      info "Para ver lo tuyo después:  git diff HEAD $RESPALDO -- ${CHOQUES[*]}"
      if ! preguntar "¿Sigo?"; then
        ((STASH)) && git stash pop -q
        git branch -D "$RESPALDO" >/dev/null 2>&1
        info "No cambié nada."; exit 0
      fi
    fi
  fi
fi

for f in "${ARCHIVOS[@]}"; do
  mkdir -p "$(dirname "$f")"
  cp -f "$TMP/$f" "$f"
  [[ -x "$TMP/$f" ]] && chmod +x "$f"
done
chmod +x install.sh config/hypr/scripts/*.sh config/hypr/scripts/lib/*.sh 2>/dev/null
git config core.fileMode >/dev/null || git config core.fileMode true
ok "${#ARCHIVOS[@]} archivos actualizados (incluye capturas/escritorio.jpg)"

# ═════════════════════ 4. Revisión ═════════════════════
titulo "4. Revisando que todo esté bien"
FALLO=0
for f in install.sh config/hypr/scripts/*.sh config/hypr/scripts/lib/*.sh; do
  bash -n "$f" 2>"$TMP/err" || { error "Sintaxis rota en $f: $(cat "$TMP/err")"; FALLO=1; }
done
((FALLO)) || ok "Sintaxis de bash"
if command -v shellcheck >/dev/null 2>&1; then
  if shellcheck -S warning install.sh config/hypr/scripts/*.sh config/hypr/scripts/lib/*.sh >"$TMP/sc" 2>&1; then ok "ShellCheck sin avisos"
  else error "ShellCheck encontró problemas:"; head -30 "$TMP/sc"; FALLO=1; fi
else info "ShellCheck no está instalado (opcional: sudo pacman -S shellcheck); lo revisa GitHub al subir."; fi
LUAC=$(command -v luac || command -v luac5.4 || true)
if [[ -n $LUAC ]]; then "$LUAC" -p config/hypr/rice.lua && ok "Sintaxis de rice.lua" || FALLO=1
else info "luac no está instalado; lo revisa GitHub al subir."; fi
ZLH=$(mktemp -d)
if HOME=$ZLH ZL_TTY=1 timeout 15 bash config/hypr/scripts/zero-lock.sh gen >"$TMP/zl.conf" 2>&1 && grep -q '^input-field {' "$TMP/zl.conf"; then
  ok "zero-lock genera su pantalla sin colgarse"
else error "zero-lock no generó su pantalla"; FALLO=1; fi
rm -rf "$ZLH"
if ((FALLO)); then
  error "Algo salió mal; dejo tu repo como estaba."
  git checkout -q -- . 2>/dev/null; git clean -fdq -- "${ARCHIVOS[@]}" 2>/dev/null
  ((STASH)) && git stash pop -q
  git branch -D "$RESPALDO" >/dev/null 2>&1
  exit 1
fi

# ═════════════════════ 5. Commit ═════════════════════
titulo "5. Guardando el cambio en git"
if [[ -z $(git config user.email || true) || -z $(git config user.name || true) ]]; then
  warn "Git no sabe quién eres (user.name / user.email)."
  N=Zer0-HMA; E=""
  if ((SI == 0)); then
    read -rp "  Tu nombre para los commits [$N]: " r || r=""; N=${r:-$N}
    read -rp "  Tu correo de GitHub (o el noreply de GitHub): " E || E=""
  fi
  [[ -n $E ]] || E="${N}@users.noreply.github.com"
  git config user.name "$N"; git config user.email "$E"
  ok "Configurado solo para este repo: $N <$E>"
fi
git add -- "${ARCHIVOS[@]}"
if git diff --cached --quiet; then
  info "No hay nada nuevo que guardar (ya estaba todo aplicado)."
else
  git commit -q -F - <<'MSG' && ok "Commit: $(git log -1 --format='%h %s')"
Versión 0.3.0: Super + L vuelve a bloquear, se recupera la 0.2.0 y captura del escritorio

zero-lock 1.2.0
- Super + L no bloqueaba: bluetoothctl se queda esperando para siempre si el
  servicio bluetooth está apagado y la config de hyprlock nunca se terminaba.
  Ahora todo lo que se consulta tiene tiempo límite y el bluetooth solo se
  revisa si hay adaptador y servicio.
- La portada de la música ya no se descarga antes de bloquear.
- Un solo bloqueo a la vez (sin procesos colgados al presionar varias veces).
- Config de emergencia si la pantalla no se genera a tiempo o hyprlock falla.
- general:grace ya no se usa (hyprlock nuevo lo quitó); preview usa --grace.
- ~/.local/bin/zero-lock es un enlace, no una copia que se queda vieja.
- Nuevo: zero-lock diagnostico. Corregidos `estado` y el hostname en Arch.

Se recupera lo que b0af96d borró sin querer de la 0.2.0
- rice.lua: hypridle, polkit y cliphist al iniciar; Super+Shift+V/F/A/E,
  workspaces 3D, animaciones.lua, blur del OSD.
- install.sh: ws3d.tsx, efectos3d.ts y los scripts perfil, animaciones,
  ws3d, portapapeles y temp (sin ellos la barra no arranca en una
  instalación nueva); hyprlock, hypridle y demás paquetes; hypridle.conf;
  --version, --enlazar, --copiar; desinstalación completa; permiso de
  ejecución de install.sh; ruta correcta de la ciudad del clima.
- GTK con tu paleta otra vez, ahora como plantillas (TEMA_GTK).
- paleta.sh encuentra la paleta guardada por la 0.2.0.

Repo
- Captura del escritorio en los README, CHANGELOG 0.3.0, VERSION 0.3.0.
- CI: revisa lib/, permisos de ejecución y que zero-lock genere sus 5
  estilos sin colgarse.
MSG
fi

# ═════════════════════ 6. Instalar y arreglar el bloqueo en vivo ═════════════════════
if ((INSTALAR)); then
  titulo "6. Instalando en tu ~/.config"
  # procesos de bloqueo que se quedaron trabados con la versión anterior
  ATORADOS=$(pgrep -fc 'zero-lock(\.sh)? (lock|bloquear)' 2>/dev/null | head -1); [[ $ATORADOS =~ ^[0-9]+$ ]] || ATORADOS=0
  pkill -f 'zero-lock(\.sh)? (lock|bloquear)' 2>/dev/null
  pkill -f 'bluetoothctl show' 2>/dev/null
  ((ATORADOS > 0)) && ok "Maté $ATORADOS procesos de bloqueo que estaban colgados" || true

  if command -v pacman >/dev/null 2>&1; then
    FALTAN=()
    for p in hyprlock hypridle cliphist hyprpolkitagent xdg-desktop-portal-hyprland; do pacman -Q "$p" >/dev/null 2>&1 || FALTAN+=("$p"); done
    if ((${#FALTAN[@]})); then
      warn "Faltan paquetes: ${FALTAN[*]}"
      if preguntar "¿Los instalo con pacman? (pide tu contraseña)"; then
        sudo pacman -S --needed "${FALTAN[@]}" && ok "Instalados" || warn "No se pudieron instalar; el bloqueo necesita al menos hyprlock"
      fi
    else ok "hyprlock, hypridle, cliphist, polkit y portal ya están instalados"; fi
  fi

  info "Corriendo el instalador del rice (solo configuraciones; respalda lo que reemplaza)…"
  OPC=(--solo-configs); ((SI)) && OPC+=(--si)
  bash "$REPO/install.sh" "${OPC[@]}" || warn "El instalador terminó con errores; revisa arriba."

  if [[ -n ${HYPRLAND_INSTANCE_SIGNATURE:-} ]]; then
    hyprctl reload >/dev/null 2>&1 && ok "Hyprland recargado (Super + L ya apunta a zero-lock)"
    if command -v hypridle >/dev/null 2>&1 && ! pgrep -x hypridle >/dev/null; then
      setsid -f hypridle >/dev/null 2>&1 && ok "hypridle arrancado (bloqueo automático)"
    fi
  else
    info "No estás dentro de Hyprland: todo se activa al iniciar sesión."
  fi

  titulo "Diagnóstico del bloqueo"
  ZL="${XDG_CONFIG_HOME:-$HOME/.config}/hypr/scripts/zero-lock.sh"
  [[ -x $ZL ]] && bash "$ZL" diagnostico
  if [[ -n ${HYPRLAND_INSTANCE_SIGNATURE:-} && -x $ZL ]] && preguntar "¿Pruebo la pantalla de bloqueo ahora? (vista previa de 6 s; mueve el mouse para salir)"; then
    bash "$ZL" preview
  fi
fi

# ═════════════════════ 7. Subir a GitHub ═════════════════════
if ((SUBIR)); then
  titulo "7. Subiendo a GitHub"
  if ! git remote get-url origin >/dev/null 2>&1; then
    warn "Este repo no tiene remoto 'origin'; no puedo subir."
  elif preguntar "¿Subo la rama $RAMA a GitHub?"; then
    if git push -u origin "$RAMA"; then
      ok "Rama $RAMA subida"
      if [[ $RAMA != main ]] && git show-ref --verify -q refs/remotes/origin/main; then
        info "La página del repo muestra el README de 'main': para que se vea la captura hay que pasar esto a main."
        if preguntar "¿Paso $RAMA a main y la subo?"; then
          git fetch -q origin main
          if git switch -q main 2>/dev/null || git switch -q -c main --track origin/main; then
            git merge -q --ff-only origin/main 2>/dev/null
            if git merge --ff-only "$RAMA" -q 2>/dev/null || git merge --no-edit "$RAMA" -m "Fusionar $RAMA (versión $VERSION_NUEVA)"; then
              git push origin main && ok "main actualizada: la captura ya sale en https://github.com/$REMOTO_ESPERADO"
            else
              git merge --abort 2>/dev/null
              warn "Hubo conflictos al pasar a main; no toqué nada. Hazlo desde GitHub con un Pull Request:"
              info "https://github.com/$REMOTO_ESPERADO/compare/main...$RAMA"
            fi
            git switch -q "$RAMA"
          else
            warn "No pude cambiarme a main; abre un Pull Request: https://github.com/$REMOTO_ESPERADO/compare/main...$RAMA"
          fi
        else
          info "Cuando quieras: https://github.com/$REMOTO_ESPERADO/compare/main...$RAMA"
        fi
      fi
    else
      error "GitHub no aceptó el push (normalmente es la contraseña: GitHub ya no acepta la de tu cuenta)."
      info "Opción fácil:  sudo pacman -S github-cli && gh auth login   y luego:  git push -u origin $RAMA"
      info "Tu commit ya está guardado en tu PC; no se pierde nada."
    fi
  fi
fi

# ═════════════════════ Resumen ═════════════════════
titulo "¡Listo!"
cat <<EOF
  Repo:             $REPO  (rama $RAMA, versión $(cat VERSION 2>/dev/null))
  Respaldo:         git reset --hard $RESPALDO
  Bloquear:         Super + L          ·  personalizar: Super + Shift + L
  ¿No bloquea?      zero-lock diagnostico   (log: ~/.cache/zero-lock/zero-lock.log)
EOF
((STASH)) && echo "  Tus cambios sin commit de antes:  git stash pop"
echo
exit 0
